WITH web_events_by_session AS (SELECT session_id, ROUND((100 * SUM(CASE WHEN page = '/checkout' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_checkout, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec FROM web_events GROUP BY session_id) SELECT s.id, s.country, webs.pct_checkout, webs.stddev_duration_sec FROM sessions s LEFT OUTER JOIN web_events_by_session webs ON s.id = webs.session_id WHERE webs.pct_checkout > 69 ORDER BY webs.stddev_duration_sec DESC, country DESC;
